		_allDefinitions.Add(new TerminalSettingDef("GuardrailDirectTopN", TerminalCategories.Ai, "6. Rule triggers (returned)", "Guardrail Direct Top N", "Maximum additional rules supplied to AI per conversation. Recall and reranking counts are derived automatically and are not padded when highly relevant rules are insufficient. Default: 4.", TerminalSettingType.Integer, 1f, 12f, 1f, "0", s => s.GuardrailDirectTopN, (s, v) => s.GuardrailDirectTopN = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("KnowledgeDirectTopN", TerminalCategories.Ai, "5. Knowledge retrieval (returned)", "Knowledge Direct Top N", "Maximum related knowledge entries supplied to AI per conversation. Takes at most this many terms in importance order, with one independent knowledge slot per term. If the highest-scoring knowledge is already occupied by an earlier term, uses the first unoccupied entry instead. Only when the limit exceeds the term count are later results for those terms added. Default: 4.", TerminalSettingType.Integer, 1f, 12f, 1f, "0", s => s.KnowledgeDirectTopN, (s, v) => s.KnowledgeDirectTopN = Convert.ToInt32(v)));
        _allDefinitions.Add(new TerminalSettingDef("RerankerDeviceDropdown", TerminalCategories.Ai, "5. Knowledge retrieval (returned)", "Reranker Device Dropdown", "Default CPU. GPU (CUDA) requires NVIDIA and optional CUDA runtime components; vector retrieval remains on CPU. Missing components, incompatible drivers, or GPU failure fall back to CPU. Restart the game fully after changing this value.", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.RerankerDeviceDropdown?.SelectedValue ?? DuelSettingsUiLocalization.Text("AF_MCM_Option_DeviceCpu", "CPU (default)"), (s, v) => { if (s.RerankerDeviceDropdown != null && v is int idx && idx >= 0 && idx < 2) s.RerankerDeviceDropdown.SelectedIndex = idx; }, null, s => s.RerankerDeviceDropdown));
		_allDefinitions.Add(new TerminalSettingDef("WorldEntityInjectMaxCount", TerminalCategories.Ai, "5. Knowledge retrieval (returned)", "World Entity Inject Maximum Count", "Maximum people, places, clans, and kingdoms injected into each AI request. In preprocessing importance order, each term first occupies one highest-scoring entity slot. For people with the same name, a clan explicitly specified by another term takes priority, followed by a kingdom. Their actual campaign-map distance from the current NPC then adds a small bonus of up to 0.15; the final score may exceed 1.00. If scope or position is unavailable, the original score is used. If the highest-scoring entity is already occupied by an earlier term, the first unoccupied entity is used instead. Secondary results are added only when the limit exceeds the term count: first up to 3 for the earliest term, then for subsequent terms in order. Default: 6.", TerminalSettingType.Integer, 1f, 20f, 1f, "0", s => s.WorldEntityInjectMaxCount, (s, v) => s.WorldEntityInjectMaxCount = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("PromptListCandidateMaxCount", TerminalCategories.Ai, "5. Knowledge retrieval (returned)", "Prompt List Candidate Maximum Count", "Number of candidates per category of items, equipment, troops, prisoners, fixed assets, and policies injected into AI. Fills to the limit when enough candidates exist; otherwise shows all. Default: 10. Does not affect entity injection limits for people, places, clans, or kingdoms.", TerminalSettingType.Integer, 1f, 30f, 1f, "0", s => s.PromptListCandidateMaxCount, (s, v) => s.PromptListCandidateMaxCount = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("DailyConversationHistoryLineLimit", TerminalCategories.Ai, "5. Compressed memory", "Daily Conversation History Line Limit", "Maximum ordinary chat-history lines carried directly in courier, free-conversation, and scene-shout requests before daily compression. AFEF facts do not count. Does not limit continued player chat or delete daily raw memories. Higher values usually increase tokens and waiting time per request. Default: 100; minimum 10, maximum 500.", TerminalSettingType.Integer, 10f, 500f, 1f, "0", s => s.DailyConversationHistoryLineLimit, (s, v) => s.DailyConversationHistoryLineLimit = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryCompressionDenominator", TerminalCategories.Ai, "5. Compressed memory", "Memory Compression Denominator", "Daily summary target length is 1/N of the day's valid conversation characters. AFEF lines are excluded and never compressed. Default: 5; minimum summary length 80.", TerminalSettingType.Integer, 3f, 10f, 1f, "0", s => s.MemoryCompressionDenominator, (s, v) => s.MemoryCompressionDenominator = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemorySummaryRequestsPerMinute", TerminalCategories.Ai, "5. Compressed memory", "Memory Summary Requests Per Minute", "Maximum concurrent NPC/day-memory summaries per minute after a day changes. Default: 3; maximum 20.", TerminalSettingType.Integer, 1f, 20f, 1f, "0", s => s.MemorySummaryRequestsPerMinute, (s, v) => s.MemorySummaryRequestsPerMinute = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryCandidateLimit", TerminalCategories.Ai, "5. Compressed memory", "Memory Candidate Limit", "Number of compressed-memory candidate blocks entering preprocessing. Default: 20; 15-20 is usually suitable. Rich-title semantic retrieval is used above this count.", TerminalSettingType.Integer, 5f, 40f, 1f, "0", s => s.MemoryCandidateLimit, (s, v) => s.MemoryCandidateLimit = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryFinalInjectCount", TerminalCategories.Ai, "5. Compressed memory", "Memory Final Inject Count", "Number of compressed memory blocks injected into the main chain. Default: 4; never exceeds the memory candidate limit.", TerminalSettingType.Integer, 2f, 20f, 1f, "0", s => s.MemoryFinalInjectCount, (s, v) => s.MemoryFinalInjectCount = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryPreprocessMode", TerminalCategories.Ai, "5. Compressed memory", "Memory Preprocess Mode", "1 = combined mode: rule Codes and memory IDs share one preprocessing JSON request. 2 = concurrent mode: rule selection and memory selection are requested simultaneously; the main chain starts only after all results parse successfully. Default: 1.", TerminalSettingType.Integer, 1f, 2f, 1f, "0", s => s.MemoryPreprocessMode, (s, v) => s.MemoryPreprocessMode = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryOverviewStartBlockCount", TerminalCategories.Ai, "5. Compressed memory", "Memory Overview Start Block Count", "Once a Hero NPC has this many compressed-memory blocks, the background process generates and continually updates an overview of past memories. Default: 5.", TerminalSettingType.Integer, 3f, 10f, 1f, "0", s => s.MemoryOverviewStartBlockCount, (s, v) => s.MemoryOverviewStartBlockCount = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MemoryOverviewTargetChars", TerminalCategories.Ai, "5. Compressed memory", "Memory Overview Target Chars", "Target character count for the overview of past memories. Default: 200; shorter text saves tokens, while longer text retains more detail.", TerminalSettingType.Integer, 100f, 1000f, 1f, "0", s => s.MemoryOverviewTargetChars, (s, v) => s.MemoryOverviewTargetChars = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableTtsSpeech", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "Enable TTS Speech", "Master switch. When disabled, NPC TTS playback stops and falls back to text-only speech bubbles.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableTtsSpeech, (s, v) => s.EnableTtsSpeech = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedEnabled", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "TTS Volc Dedicated Enabled", "Selects V1 or V3 HTTP unidirectional synthesis (including Agent Plan) by API URL. Both collect all audio before playback; existing settings are not migrated automatically.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.TtsVolcDedicatedEnabled, (s, v) => s.TtsVolcDedicatedEnabled = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedApiUrl", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "TTS Volc Dedicated API URL", "V1: https://openspeech.bytedance.com/api/v1/tts; V3: https://openspeech.bytedance.com/api/v3/tts/unidirectional; Agent Plan: https://openspeech.bytedance.com/api/v3/plan/tts/unidirectional (HTTP, not SSE/WS).", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedApiUrl ?? "", (s, v) => s.TtsVolcDedicatedApiUrl = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedApiKey", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "Volcengine dedicated token / API key", "V1 uses your legacy token; its HTTP header is Authorization: Bearer; followed by the token. V3 uses the corresponding speech-service API key (X-Api-Key). Agent Plan requires its dedicated API key; do not reuse the old token.", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedApiKey ?? "", (s, v) => s.TtsVolcDedicatedApiKey = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedAppKey", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "TTS Volc Dedicated App Key", "V1 requires app.appid. V3 API-key authentication does not use it, so it may be blank. Switching protocols does not clear the old value.", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedAppKey ?? "", (s, v) => s.TtsVolcDedicatedAppKey = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedResourceId", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "TTS Volc Dedicated Resource ID", "Written to the X-Api-Resource-Id request header. The resource and voice must be enabled and authorized; synthesis voices from model 2.0 use V3. Accepted values include seed-tts-1.0 / seed-tts-1.0-concurr / seed-tts-2.0 / seed-icl-1.0 / seed-icl-1.0-concurr / seed-icl-2.0.", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedResourceId ?? "", (s, v) => s.TtsVolcDedicatedResourceId = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedSpeaker", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "Volcengine dedicated voice ID", "Maps to voice_type in V1 and speaker in V3. It must match the resource ID and account authorization; the old voice is not replaced automatically.", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedSpeaker ?? "", (s, v) => s.TtsVolcDedicatedSpeaker = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedAdditionsJson", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "Volcengine dedicated extra parameters (JSON object)", "Written to request.extra_param in V1 or req_params.additions in V3, both as JSON strings. Use parameters supported by the selected endpoint.", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedAdditionsJson ?? "", (s, v) => s.TtsVolcDedicatedAdditionsJson = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedAudioFormat", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "TTS Volc Dedicated Audio Format", "Supports wav or pcm only. V1 requests the selected format unchanged. V3 always receives PCM and wraps it as selected here, retaining the current player.", TerminalSettingType.Text, 0f, 0f, 0f, "", s => s.TtsVolcDedicatedAudioFormat ?? "", (s, v) => s.TtsVolcDedicatedAudioFormat = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedSampleRate", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "TTS Volc Dedicated Sample Rate", "Recommended values: 8000 / 16000 / 24000 Hz. V3 also supports 22050 Hz; arbitrary integer sample rates are not accepted by V3.", TerminalSettingType.Integer, 8000f, 24000f, 1f, "0", s => s.TtsVolcDedicatedSampleRate, (s, v) => s.TtsVolcDedicatedSampleRate = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedVolume", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "TTS Volc Dedicated Volume", "Used only by the main playback chain for ordinary dialogue/test speech (agentIndex<0). For the scene-shout lip-sync chain, adjust Lip-sync chain volume.", TerminalSettingType.FloatingInteger, 0f, 1f, 0.05f, "0.00", s => s.TtsVolcDedicatedVolume, (s, v) => s.TtsVolcDedicatedVolume = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedSpeed", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "TTS Volc Dedicated Speed", "V1 supports 0.1–2.0 times normal; V3 supports 0.5–2.0 (1.0 is normal). A value that is too low after switching to V3 produces an error and is not changed automatically.", TerminalSettingType.FloatingInteger, 0.1f, 2f, 0.05f, "0.00", s => s.TtsVolcDedicatedSpeed, (s, v) => s.TtsVolcDedicatedSpeed = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsSceneUseWinmmAudible", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "TTS Scene Use Winmm Audible", "When enabled, scene NPC audio uses winmm, while the lip-sync chain drives mouth movements silently. When disabled, scene NPC audio uses the lip-sync chain and can be adjusted with Lip-sync chain volume.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.TtsSceneUseWinmmAudible, (s, v) => s.TtsSceneUseWinmmAudible = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsLipSyncSoundEventVolume", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "TTS Lip Sync Sound Event Volume", "SoundEvent volume for Rhubarb lip-sync. Controls audible scene volume only when Scene audio through winmm (prevent echo) is disabled.", TerminalSettingType.FloatingInteger, 0f, 1f, 0.05f, "0.00", s => s.TtsLipSyncSoundEventVolume, (s, v) => s.TtsLipSyncSoundEventVolume = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("TestTtsVolcDedicatedVoice", TerminalCategories.Ai, "7. Volcengine TTS (dedicated)", "Test TTS Volc Dedicated Voice", "Tests the fixed phrase “At your service, traveler!” using the current API URL and credential. Real synthesis may incur charges.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.TestTtsVolcDedicatedVoice?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EnableDeepTrace", TerminalCategories.Ai, "4. Developer options", "Enable Deep Trace", "⚠️ Advanced debugging feature! When enabled, intercepts all UI clicks, state transitions, and low-level code stacks (Trace). Produces a very large log and is intended for developers investigating issues only. Ordinary players should not enable it.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableDeepTrace, (s, v) => s.EnableDeepTrace = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableDevEditHistory", TerminalCategories.Ai, "4. Developer options", "Enable Dev Edit History", "Adds a Developer data-management entry to the town main menu for viewing and editing any NPC dialogue history, credit/debts, persona, and background. The player notoriety/history popup on the character screen (C) also enables player history editing.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableDevEditHistory, (s, v) => s.EnableDevEditHistory = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableAdultHeroPersonaAutoGeneration", TerminalCategories.Ai, "4. Developer options", "Enable Adult Hero Persona Auto Generation", "When enabled, the preprocessing API generates persona and history for hero children when they become adults. Existing persona or background is never overwritten.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableAdultHeroPersonaAutoGeneration, (s, v) => s.EnableAdultHeroPersonaAutoGeneration = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableNpcPersonaEventEvolution", TerminalCategories.Diplomacy, "Weekly reports / bulletins", "Event-driven NPC persona evolution", "Default: off. New confirmed bulletin events can change NPC personas. Uses the auxiliary API with merged, rate-limited requests. Turning off discards pending updates but keeps existing changes. Requires bulletin mode; auto-publishing is not required.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNpcPersonaEventEvolution, (s, v) => s.EnableNpcPersonaEventEvolution = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableModLogicLog", TerminalCategories.Ai, "4. Developer options", "Enable Mod Logic Log", "Master logic-log switch. When disabled, Mod_Logic.txt is no longer written.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableModLogicLog, (s, v) => s.EnableModLogicLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableVerboseModLogicLog", TerminalCategories.Ai, "4. Developer options", "Enable Verbose Mod Logic Log", "Enable only while investigating an issue. Writes detailed Mod_Logic diagnostics and may produce many lines in large campaigns.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableVerboseModLogicLog, (s, v) => s.EnableVerboseModLogicLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableObservabilityLog", TerminalCategories.Ai, "4. Developer options", "Enable Observability Log", "Structured observability-log switch. When disabled, Observability.jsonl is no longer written.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableObservabilityLog, (s, v) => s.EnableObservabilityLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableHitRateStatsLog", TerminalCategories.Ai, "4. Developer options", "Enable Hit Rate Stats Log", "Hit-rate statistics log switch. When disabled, HitRate_Stats.txt is no longer written.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableHitRateStatsLog, (s, v) => s.EnableHitRateStatsLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableTokenStatsLog", TerminalCategories.Ai, "4. Developer options", "Enable Token Stats Log", "Token statistics log switch. When disabled, Token_Stats.txt is no longer written.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableTokenStatsLog, (s, v) => s.EnableTokenStatsLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableEventLogs", TerminalCategories.Ai, "4. Developer options", "Enable Event Logs", "Event-system weekly-report log switch. When disabled, Event_Logs.txt is no longer written.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableEventLogs, (s, v) => s.EnableEventLogs = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnablePerformanceMonitor", TerminalCategories.Ai, "4. Developer options", "Enable Performance Monitor", "Every 30 seconds writes FPS, slow frames, and total frame time to Mod_Logic.txt. Tick/Scope timings are collected only with verbose debug logs also enabled; ordinary play does not incur per-Scope statistics costs. Off by default.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnablePerformanceMonitor, (s, v) => s.EnablePerformanceMonitor = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableDeferredDailyMaintenance", TerminalCategories.Ai, "4. Developer options", "Enable Deferred Daily Maintenance", "Daily settlement registers maintenance jobs; memory overview, kingdom maintenance, and weekly-report preparation run later in bounded per-frame batches. Advances on campaign-map ticks and is not paused by travel. Enabled by default.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableDeferredDailyMaintenance, (s, v) => s.EnableDeferredDailyMaintenance = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("DailyMaintenanceFrameBudgetMs", TerminalCategories.Ai, "4. Developer options", "Daily Maintenance Frame Budget Ms", "When deferred maintenance is enabled, work advances within this per-frame budget only when jobs are pending; player travel does not pause it. Default: 3. Higher values finish background work faster but are more likely to cause frame spikes.", TerminalSettingType.Integer, 1f, 10f, 1f, "0", s => s.DailyMaintenanceFrameBudgetMs, (s, v) => s.DailyMaintenanceFrameBudgetMs = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableFreezeDumpCapture", TerminalCategories.Ai, "4. Developer options", "Enable Freeze Dump Capture", "Only while AF free-conversation AI mode or scene shout is processing, creates a compact thread dump after five seconds without a main-thread heartbeat. Disabled for ordinary chat, non-AI play, and native saving. Enabled by default.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableFreezeDumpCapture, (s, v) => s.EnableFreezeDumpCapture = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("LogCleanupIntervalDropdown", TerminalCategories.Ai, "4. Developer options", "Log Cleanup Interval Dropdown", "Periodically clears current log files under AnimusForge/Logs by real time. Files and the UTF-8 BOM are retained. Default: every 3 days.", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.LogCleanupIntervalDropdown?.SelectedValue ?? "", (s, v) => { if (s.LogCleanupIntervalDropdown != null && v is int idx && idx >= 0 && idx < s.LogCleanupIntervalDropdown.Count) { var dd = s.LogCleanupIntervalDropdown; dd.SelectedIndex = idx; s.LogCleanupIntervalDropdown = dd; } }, null, s => s.LogCleanupIntervalDropdown));
		_allDefinitions.Add(new TerminalSettingDef("OpenAfdianSupportLink", TerminalCategories.Ai, "0. Support", "Open Afdian Support Link", "Opens the Afdian page in the system default browser.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.OpenAfdianSupportLink?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("ShoutKey", TerminalCategories.Scene, "3. Scene shout", "Shout Key", "Hold this key in a scene to preview and expand shout range; release it to open the speech input. Default: T.", TerminalSettingType.Hotkey, 0f, 0f, 0f, "", s => s.ShoutKey ?? "", (s, v) => s.ShoutKey = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("ShoutSpecialMenuKey", TerminalCategories.Scene, "3. Scene shout", "Shout Special Menu Key", "Hold this key in a scene to preview and expand shout range; release it to open the complex interaction menu. Default: Y.", TerminalSettingType.Hotkey, 0f, 0f, 0f, "", s => s.ShoutSpecialMenuKey ?? "", (s, v) => s.ShoutSpecialMenuKey = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("TerminalKey", TerminalCategories.Scene, "3. Scene shout", "Terminal Key", "Press this key on the campaign map or in a campaign scene to open the AnimusForge terminal. Unavailable during conversations, text input or other menus. Default: U.", TerminalSettingType.Hotkey, 0f, 0f, 0f, "", s => s.TerminalKey ?? "", (s, v) => s.TerminalKey = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("SceneTauntGoldPickupKey", TerminalCategories.Scene, "3. Scene shout", "Scene Taunt Gold Pickup Key", "During a scene taunt conflict, approach dropped coins after an NPC falls and press this key to collect them. Default: F.", TerminalSettingType.Hotkey, 0f, 0f, 0f, "", s => s.SceneTauntGoldPickupKey ?? "", (s, v) => s.SceneTauntGoldPickupKey = v?.ToString() ?? ""));
		_allDefinitions.Add(new TerminalSettingDef("ShoutInitialRangeMeters", TerminalCategories.Scene, "3. Scene shout", "Shout Initial Range Meters", "Base shout range used when T/Y is pressed. Default: 4 m.", TerminalSettingType.FloatingInteger, 1f, 150f, 0.05f, "0.0", s => s.ShoutInitialRangeMeters, (s, v) => s.ShoutInitialRangeMeters = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("ShoutMaxRangeMeters", TerminalCategories.Scene, "3. Scene shout", "Shout Maximum Range Meters", "Maximum shout range while holding T/Y, capped at 150 m. Larger ranges show more preview markers.", TerminalSettingType.FloatingInteger, 1f, 150f, 0.05f, "0.0", s => s.ShoutMaxRangeMeters, (s, v) => s.ShoutMaxRangeMeters = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("ShoutMinTokens", TerminalCategories.Scene, "3. Scene shout", "Shout Minimum Tokens", "Minimum character count of a scene-shout reply. Default: 40.", TerminalSettingType.Integer, 1f, 500f, 1f, "0", s => s.ShoutMinTokens, (s, v) => s.ShoutMinTokens = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ShoutMaxTokens", TerminalCategories.Scene, "3. Scene shout", "Shout Maximum Tokens", "Maximum character count of a scene-shout reply. Default: 200; values below the minimum are treated as the minimum at runtime.", TerminalSettingType.Integer, 1f, 500f, 1f, "0", s => s.ShoutMaxTokens, (s, v) => s.ShoutMaxTokens = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ShoutThoughtMinTokens", TerminalCategories.Scene, "3. Scene shout", "Shout Thought Minimum Tokens", "Minimum character count of the parenthesized inner-thought section in the scene-shout reply format. Minimum: 40; default: 200.", TerminalSettingType.Integer, 40f, 2000f, 1f, "0", s => s.ShoutThoughtMinTokens, (s, v) => s.ShoutThoughtMinTokens = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("DisableShoutInnerThoughtPrompt", TerminalCategories.Scene, "3. Scene shout", "Disable Shout Inner Thought Prompt", "When enabled, scene-shout requests no longer require inner-thought output and keep only the action and spoken-line format.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.DisableShoutInnerThoughtPrompt, (s, v) => s.DisableShoutInnerThoughtPrompt = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("BubbleFontSize", TerminalCategories.Scene, "3. Scene shout", "Bubble Font Size", "Sets the font size of text in scene-shout bubbles.", TerminalSettingType.Integer, 10f, 40f, 1f, "0", s => s.BubbleFontSize, (s, v) => s.BubbleFontSize = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("SceneConversationTimeoutSecondsPerVisibleCharacter", TerminalCategories.Scene, "3. Scene shout", "Scene Conversation Timeout Seconds Per Visible Character", "Dynamically extends the idle dismissal time for scene conversations based on the visible player and NPC character count in the current exchange. Default: 1 second per character.", TerminalSettingType.FloatingInteger, 0.5f, 3f, 0.05f, "0.0", s => s.SceneConversationTimeoutSecondsPerVisibleCharacter, (s, v) => s.SceneConversationTimeoutSecondsPerVisibleCharacter = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnablePassiveStareReaction", TerminalCategories.Scene, "3. Scene shout", "Enable Automatic Stare Reaction", "When enabled, staring at one NPC for the configured time can start a passive scene exchange. Disabled by default.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnablePassiveStareReaction, (s, v) => s.EnablePassiveStareReaction = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("PassiveStareTriggerSeconds", TerminalCategories.Scene, "3. Scene shout", "Passive Stare Trigger Seconds", "How long the player must stare at one NPC before a passive reaction triggers. Set to 0 to disable it. Default: 15 seconds when enabled.", TerminalSettingType.Integer, 0f, 120f, 1f, "0", s => s.PassiveStareTriggerSeconds, (s, v) => s.PassiveStareTriggerSeconds = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MinimumPositiveNpcRelationGain", TerminalCategories.Scene, "3. Scene shout", "Minimum Positive NPC Relation/Private Gain", "Minimum points applied to native relation and private relation when an NPC mood outcome is positive. 0 keeps the original mood delta. Default: 1.", TerminalSettingType.Integer, 0f, 20f, 1f, "0", s => s.MinimumPositiveNpcRelationGain, (s, v) => s.MinimumPositiveNpcRelationGain = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnablePeaceSceneConflict", TerminalCategories.Scene, "3. Scene shout", "Enable Peace Scene Conflict", "When enabled, direct attacks on NPCs in peaceful scenes can trigger this mod scene conflict. When disabled, direct attacks return fully to native damage handling; dialogue arguments and taunts can still escalate conflict.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnablePeaceSceneConflict, (s, v) => s.EnablePeaceSceneConflict = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("ShoutInputUiBackgroundDropdown", TerminalCategories.Scene, "3. Scene shout", "Shout Input UI Background Dropdown", "Affects only the shout input box. Default is transparent black; transparent white or pink are also available.", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.ShoutInputUiBackgroundDropdown?.SelectedValue ?? "", (s, v) => { if (s.ShoutInputUiBackgroundDropdown != null && v is int idx && idx >= 0 && idx < s.ShoutInputUiBackgroundDropdown.Count) { var dd = s.ShoutInputUiBackgroundDropdown; dd.SelectedIndex = idx; s.ShoutInputUiBackgroundDropdown = dd; } }, null, s => s.ShoutInputUiBackgroundDropdown));
		_allDefinitions.Add(new TerminalSettingDef("MinimumClanTier", TerminalCategories.Duel, "2. Duel rules", "Minimum Clan Tier", "", TerminalSettingType.Integer, 0f, 6f, 1f, "0", s => s.MinimumClanTier, (s, v) => s.MinimumClanTier = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("HealthThreshold", TerminalCategories.Duel, "2. Duel rules", "Health Threshold", "", TerminalSettingType.FloatingInteger, 0.1f, 0.5f, 0.1f, "#0%", s => s.HealthThreshold, (s, v) => s.HealthThreshold = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableDuelLoserClanRenownPenalty", TerminalCategories.Duel, "2. Duel rules", "Enable Duel Loser Clan Renown Penalty", "After a formal duel is settled, the winning clan gains exactly the renown actually deducted from the losing clan. No settlement occurs if both participants belong to the same clan or either has no clan. Losing renown never falls below 0, and already attained clan tiers are not forcibly reduced.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableDuelLoserClanRenownPenalty, (s, v) => s.EnableDuelLoserClanRenownPenalty = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("DuelLoserClanRenownPenaltyMinimum", TerminalCategories.Duel, "2. Duel rules", "Duel Loser Clan Renown Penalty Minimum", "Minimum clan renown deducted from the loser each time. Default: 20; if the clan has insufficient renown, the deduction stops at 0.", TerminalSettingType.Integer, 0f, 1000f, 1f, "0", s => s.DuelLoserClanRenownPenaltyMinimum, (s, v) => s.DuelLoserClanRenownPenaltyMinimum = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("DuelLoserClanRenownPenaltyPercent", TerminalCategories.Duel, "2. Duel rules", "Duel Loser Clan Renown Penalty Percent", "Percentage deduction based on the losing clan's current renown before settlement; the larger of this amount and the minimum deduction is used. Default: 3%.", TerminalSettingType.Integer, 0f, 50f, 1f, "0", s => s.DuelLoserClanRenownPenaltyPercent, (s, v) => s.DuelLoserClanRenownPenaltyPercent = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("DuelLoserClanRenownPenaltyMaximum", TerminalCategories.Duel, "2. Duel rules", "Duel Loser Clan Renown Penalty Maximum", "Maximum clan renown deducted for one duel. Default: 150; 0 means no cap.", TerminalSettingType.Integer, 0f, 5000f, 1f, "0", s => s.DuelLoserClanRenownPenaltyMaximum, (s, v) => s.DuelLoserClanRenownPenaltyMaximum = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableNpcBattleEquipmentRestore", TerminalCategories.Characters, "10. Items and trade", "Enable NPC Battle Equipment Restore", "When enabled, equipped items that NPCs lose through gifts, trades, or post-battle capture return to their original slots after 3 full days. Other equipment already in those slots is never overwritten. When disabled, NPCs can still hand over equipment, but no new restoration tasks are registered and existing tasks are not executed. Existing tasks resume when re-enabled. Enabled by default.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNpcBattleEquipmentRestore, (s, v) => s.EnableNpcBattleEquipmentRestore = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableProactiveNpcRequests", TerminalCategories.Characters, "7. NPC proactive contact", "Enable Proactive NPC Requests", "When enabled, NPC parties with explicit needs can proactively catch up with the player on the campaign map and initiate dialogue.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableProactiveNpcRequests, (s, v) => s.EnableProactiveNpcRequests = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestTestMode", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Test Mode", "When enabled, Tier 0 players can trigger proactive contact. Use high probabilities and short cooldowns to test contact. Disabled by default for normal play.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.ProactiveNpcRequestTestMode, (s, v) => s.ProactiveNpcRequestTestMode = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestMinClanTier", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Minimum Clan Tier", "Applies when test mode is disabled. NPC proactive contact does not trigger if the player clan tier is below this value.", TerminalSettingType.Integer, 0f, 6f, 1f, "0", s => s.ProactiveNpcRequestMinClanTier, (s, v) => s.ProactiveNpcRequestMinClanTier = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestChancePercent", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Chance Percent", "Scaling value for candidate NPC trigger probability. Normal-play default: 35; can be raised to 100 for testing.", TerminalSettingType.Integer, 0f, 100f, 1f, "0", s => s.ProactiveNpcRequestChancePercent, (s, v) => s.ProactiveNpcRequestChancePercent = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestScanIntervalHours", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Scan Interval Hours", "In-game hours between scans of nearby NPC parties with needs. Normal-play default: 6 hours.", TerminalSettingType.Integer, 1f, 24f, 1f, "0", s => s.ProactiveNpcRequestScanIntervalHours, (s, v) => s.ProactiveNpcRequestScanIntervalHours = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestGlobalCooldownHours", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Global Cooldown Hours", "Hours before the next proactive contact can start after any proactive contact starts. Normal-play default: 24 hours.", TerminalSettingType.Integer, 0f, 240f, 1f, "0", s => s.ProactiveNpcRequestGlobalCooldownHours, (s, v) => s.ProactiveNpcRequestGlobalCooldownHours = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestHeroCooldownDays", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Hero Cooldown Days", "Days before the same NPC can approach the player again with the same type of need after proactive contact. Normal-play default: 14 days.", TerminalSettingType.Integer, 0f, 60f, 1f, "0", s => s.ProactiveNpcRequestHeroCooldownDays, (s, v) => s.ProactiveNpcRequestHeroCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestDistanceMultiplier", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Distance Multiplier", "Maximum distance between a candidate NPC and the player is the player vision range multiplied by this value. Normal-play default: 1.0.", TerminalSettingType.FloatingInteger, 0.5f, 5f, 0.05f, "0.0", s => s.ProactiveNpcRequestDistanceMultiplier, (s, v) => s.ProactiveNpcRequestDistanceMultiplier = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestFoodDaysThreshold", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Food Days Threshold", "Food-shortage contact can trigger when an NPC party has at most this many days of food left or is already starving. Normal-play default: 2 days.", TerminalSettingType.Integer, 0f, 15f, 1f, "0", s => s.ProactiveNpcRequestFoodDaysThreshold, (s, v) => s.ProactiveNpcRequestFoodDaysThreshold = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestMoneyGoldThreshold", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Money Gold Threshold", "Money-shortage contact can trigger when the NPC lord available cash is below this value. At runtime, it never falls below the native party cash floor. Default: 5000.", TerminalSettingType.Integer, 1f, 50000f, 1f, "0", s => s.ProactiveNpcRequestMoneyGoldThreshold, (s, v) => s.ProactiveNpcRequestMoneyGoldThreshold = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestMoneyWageDaysThreshold", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Money Wage Days Threshold", "Money-shortage contact can trigger when an NPC lord cash can pay at most this many days of wages. 0 checks only the cash threshold and unpaid wages. Normal-play default: 2 days.", TerminalSettingType.Integer, 0f, 30f, 1f, "0", s => s.ProactiveNpcRequestMoneyWageDaysThreshold, (s, v) => s.ProactiveNpcRequestMoneyWageDaysThreshold = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestTroopRatioThresholdPercent", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Troop Ratio Threshold Percent", "Troop-shortage contact can trigger when the NPC lord current party size is below this percentage of the party-size limit. Normal-play default: 45; can be raised to 90 or 100 for testing.", TerminalSettingType.Integer, 1f, 100f, 1f, "0", s => s.ProactiveNpcRequestTroopRatioThresholdPercent, (s, v) => s.ProactiveNpcRequestTroopRatioThresholdPercent = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestPrisonerRatioThresholdPercent", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Prisoner Ratio Threshold Percent", "An NPC lord can initiate prisoner overload or ransom contact when the current prisoner count reaches this percentage of prisoner capacity. The normal-play default is 90; 100 means nearly full capacity, and values above 100 trigger only when over capacity.", TerminalSettingType.Integer, 1f, 150f, 1f, "0", s => s.ProactiveNpcRequestPrisonerRatioThresholdPercent, (s, v) => s.ProactiveNpcRequestPrisonerRatioThresholdPercent = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestLowMoraleThreshold", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Low Morale Threshold", "Low-morale contact can trigger when an NPC lord party morale is at or below this value. 0 disables this need. Normal-play default: 35.", TerminalSettingType.Integer, 0f, 100f, 1f, "0", s => s.ProactiveNpcRequestLowMoraleThreshold, (s, v) => s.ProactiveNpcRequestLowMoraleThreshold = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestMountRatioThresholdPercent", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Mount Ratio Threshold Percent", "Mount-shortage/low-mobility contact can trigger when mounts in the NPC lord party are below this percentage of party members. 0 disables this need. Normal-play default: 25.", TerminalSettingType.Integer, 0f, 100f, 1f, "0", s => s.ProactiveNpcRequestMountRatioThresholdPercent, (s, v) => s.ProactiveNpcRequestMountRatioThresholdPercent = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestOverburdenRatioThresholdPercent", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Overburden Ratio Threshold Percent", "Overburden-pressure contact can trigger when the NPC lord party total load reaches this percentage of inventory capacity. Normal-play default: 92.", TerminalSettingType.Integer, 50f, 150f, 1f, "0", s => s.ProactiveNpcRequestOverburdenRatioThresholdPercent, (s, v) => s.ProactiveNpcRequestOverburdenRatioThresholdPercent = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestClanGoldThreshold", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Clan Gold Threshold", "Clan financial-pressure contact can trigger when the NPC clan treasury is below this value. 0 ignores the treasury. Normal-play default: 15000.", TerminalSettingType.Integer, 0f, 200000f, 1f, "0", s => s.ProactiveNpcRequestClanGoldThreshold, (s, v) => s.ProactiveNpcRequestClanGoldThreshold = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestClanDebtThreshold", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Clan Debt Threshold", "Clan financial-pressure contact can trigger when the NPC clan debt to the kingdom exceeds this value. 0 ignores debt. Normal-play default: 5000.", TerminalSettingType.Integer, 0f, 200000f, 1f, "0", s => s.ProactiveNpcRequestClanDebtThreshold, (s, v) => s.ProactiveNpcRequestClanDebtThreshold = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestMarriageAdultClanThreshold", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Marriage Adult Clan Threshold", "Succession/marriage-pressure contact can trigger when the number of adult core members of the NPC clan is at or below this value and an adult unmarried clan member exists. Normal-play default: 3.", TerminalSettingType.Integer, 1f, 12f, 1f, "0", s => s.ProactiveNpcRequestMarriageAdultClanThreshold, (s, v) => s.ProactiveNpcRequestMarriageAdultClanThreshold = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestFiefLoyaltyThreshold", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Fief Loyalty Threshold", "Fief-governance-anxiety contact can trigger when loyalty in an NPC clan fief is at or below this value. 0 ignores loyalty. Normal-play default: 35.", TerminalSettingType.Integer, 0f, 100f, 1f, "0", s => s.ProactiveNpcRequestFiefLoyaltyThreshold, (s, v) => s.ProactiveNpcRequestFiefLoyaltyThreshold = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestFiefSecurityThreshold", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Fief Security Threshold", "Fief-governance-anxiety contact can trigger when security in an NPC clan fief is at or below this value. 0 ignores security. Normal-play default: 35.", TerminalSettingType.Integer, 0f, 100f, 1f, "0", s => s.ProactiveNpcRequestFiefSecurityThreshold, (s, v) => s.ProactiveNpcRequestFiefSecurityThreshold = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestFiefGarrisonThreshold", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Fief Garrison Threshold", "Fief-governance-anxiety contact can trigger when the garrison in an NPC clan fief is at or below this value. 0 ignores garrisons. Normal-play default: 80.", TerminalSettingType.Integer, 0f, 1000f, 1f, "0", s => s.ProactiveNpcRequestFiefGarrisonThreshold, (s, v) => s.ProactiveNpcRequestFiefGarrisonThreshold = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestIsolationInfluenceThreshold", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Isolation Influence Threshold", "Combined with ally count, lack-of-allies contact can trigger when NPC clan influence is at or below this value. 0 ignores influence. Normal-play default: 40.", TerminalSettingType.Integer, 0f, 500f, 1f, "0", s => s.ProactiveNpcRequestIsolationInfluenceThreshold, (s, v) => s.ProactiveNpcRequestIsolationInfluenceThreshold = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestIsolationMaxFriendlyClans", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Isolation Maximum Friendly Clans", "Combined with low influence or hostile relations, lack-of-allies contact can trigger when the number of friendly clans in the same kingdom with an NPC clan relation of at least 20 is at or below this value. Normal-play default: 1.", TerminalSettingType.Integer, 0f, 10f, 1f, "0", s => s.ProactiveNpcRequestIsolationMaxFriendlyClans, (s, v) => s.ProactiveNpcRequestIsolationMaxFriendlyClans = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcKnownMajorMultiplier", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Known Major Multiplier", "Multiplier for need-driven proactive-contact probability when the NPC already knows the player major history. Default: 2.0.", TerminalSettingType.FloatingInteger, 1f, 5f, 0.05f, "0.0", s => s.ProactiveNpcKnownMajorMultiplier, (s, v) => s.ProactiveNpcKnownMajorMultiplier = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcNotorietyChanceMultiplier", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Notoriety Chance Multiplier", "Multiplier converting effective player notoriety into additional NPC proactive-contact probability. Normal-play default: 0.35.", TerminalSettingType.FloatingInteger, 0f, 3f, 0.05f, "0.0", s => s.ProactiveNpcNotorietyChanceMultiplier, (s, v) => s.ProactiveNpcNotorietyChanceMultiplier = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcMinNeedUrgency", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Minimum Need Urgency", "Minimum need urgency required for NPC proactive contact; treated as 0 at runtime in test mode. Normal-play default: 60.", TerminalSettingType.Integer, 0f, 100f, 1f, "0", s => s.ProactiveNpcMinNeedUrgency, (s, v) => s.ProactiveNpcMinNeedUrgency = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestTypeFatigueDays", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Type Fatigue Days", "In-game days of greatly reduced trigger probability for a request type after the player receives it. 0 disables type fatigue. Default: 10 days.", TerminalSettingType.Integer, 0f, 60f, 1f, "0", s => s.ProactiveNpcRequestTypeFatigueDays, (s, v) => s.ProactiveNpcRequestTypeFatigueDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestTypeFatigueMultiplier", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Type Fatigue Multiplier", "During type fatigue, multiplies both need-driven and notoriety-driven probabilities by this value and lowers the need priority among candidates. Default: 0.20.", TerminalSettingType.FloatingInteger, 0f, 1f, 0.05f, "0.00", s => s.ProactiveNpcRequestTypeFatigueMultiplier, (s, v) => s.ProactiveNpcRequestTypeFatigueMultiplier = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestMountShortageWeight", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Mount Shortage Weight", "Candidate-weight and trigger-probability multiplier for mount-shortage/purchase requests in map proactive contact and proactive letters. Default: 0.35; 0 retains the need check but prevents proactive initiation. Map pursuit still uses 1.00 in test mode.", TerminalSettingType.FloatingInteger, 0f, 1f, 0.05f, "0.00", s => s.ProactiveNpcRequestMountShortageWeight, (s, v) => s.ProactiveNpcRequestMountShortageWeight = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestRomanticInteractionGlobalCooldownDays", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Romantic Interaction Global Cooldown Days", "Shared hard cooldown for intimate interactions with an opposite-sex NPC whose private relation is above 30, across map pursuit, proactive letters, and companion chats within the party. Default: 21 days.", TerminalSettingType.Integer, 1f, 120f, 1f, "0", s => s.ProactiveNpcRequestRomanticInteractionGlobalCooldownDays, (s, v) => s.ProactiveNpcRequestRomanticInteractionGlobalCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestGreetingGlobalCooldownDays", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Greeting Global Cooldown Days", "Shared hard cooldown after an NPC with a private relation above 20 proactively catches up with the player or sends a greeting letter. Default: 42 days.", TerminalSettingType.Integer, 1f, 120f, 1f, "0", s => s.ProactiveNpcRequestGreetingGlobalCooldownDays, (s, v) => s.ProactiveNpcRequestGreetingGlobalCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestTerritorialInterrogationSettlementRangeMultiplier", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Territorial Interrogation Settlement Range Multiplier", "When the player is within the player vision range multiplied by this value of a kingdom settlement, its lords of a different culture who do not know the player history can proactively question the player origin and purpose. Default: 3.0.", TerminalSettingType.FloatingInteger, 0.5f, 10f, 0.05f, "0.0", s => s.ProactiveNpcRequestTerritorialInterrogationSettlementRangeMultiplier, (s, v) => s.ProactiveNpcRequestTerritorialInterrogationSettlementRangeMultiplier = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("ProactiveNpcRequestTerritorialInterrogationGlobalCooldownDays", TerminalCategories.Characters, "7. NPC proactive contact", "Proactive NPC Request Territorial Interrogation Global Cooldown Days", "Shared hard cooldown after a territorial interrogation successfully starts. Default: 42 days.", TerminalSettingType.Integer, 1f, 180f, 1f, "0", s => s.ProactiveNpcRequestTerritorialInterrogationGlobalCooldownDays, (s, v) => s.ProactiveNpcRequestTerritorialInterrogationGlobalCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableNpcInitiatedLetters", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "Enable NPC Initiated Letters", "Allows NPCs who already know the player and have a sufficient combined intimacy score to send real couriers proactively.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNpcInitiatedLetters, (s, v) => s.EnableNpcInitiatedLetters = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterTestMode", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter Test Mode", "Raises the trigger probability to 100% and removes proactive-letter cooldowns. Still requires the NPC to know the player, have a valid location, and have a real motive.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.NpcInitiatedLetterTestMode, (s, v) => s.NpcInitiatedLetterTestMode = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterMinBondScore", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter Minimum Bond Score", "Minimum candidate score after averaging private relation and the trust value used for letters. Default: 10.", TerminalSettingType.Integer, 0f, 100f, 1f, "0", s => s.NpcInitiatedLetterMinBondScore, (s, v) => s.NpcInitiatedLetterMinBondScore = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterScanIntervalHours", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter Scan Interval Hours", "In-game hours between scans of proactive-letter candidates. Default: 24 hours.", TerminalSettingType.Integer, 1f, 168f, 1f, "0", s => s.NpcInitiatedLetterScanIntervalHours, (s, v) => s.NpcInitiatedLetterScanIntervalHours = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterChanceMultiplier", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter Chance Multiplier", "Probability per scan equals the combined intimacy score multiplied by this value. Default: 0.25, so a score of 100 gives a 25% chance.", TerminalSettingType.FloatingInteger, 0f, 2f, 0.05f, "0.00", s => s.NpcInitiatedLetterChanceMultiplier, (s, v) => s.NpcInitiatedLetterChanceMultiplier = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterGlobalCooldownDays", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter Global Cooldown Days", "In-game days before another proactive letter can start after any NPC proactively sends one. Default: 5 days.", TerminalSettingType.Integer, 0f, 60f, 1f, "0", s => s.NpcInitiatedLetterGlobalCooldownDays, (s, v) => s.NpcInitiatedLetterGlobalCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterLowScoreCooldownDays", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter Low Score Cooldown Days", "Sender cooldown for an NPC with the lowest combined score. Default: 45 days.", TerminalSettingType.Integer, 1f, 120f, 1f, "0", s => s.NpcInitiatedLetterLowScoreCooldownDays, (s, v) => s.NpcInitiatedLetterLowScoreCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterHighScoreCooldownDays", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter High Score Cooldown Days", "Sender cooldown for an NPC with a combined score of 100. Default: 14 days.", TerminalSettingType.Integer, 1f, 60f, 1f, "0", s => s.NpcInitiatedLetterHighScoreCooldownDays, (s, v) => s.NpcInitiatedLetterHighScoreCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterQuietDays", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter Quiet Days", "Minimum in-game days after communicating with this NPC through any channel before a proactive letter is allowed. Default: 3 days.", TerminalSettingType.Integer, 0f, 30f, 1f, "0", s => s.NpcInitiatedLetterQuietDays, (s, v) => s.NpcInitiatedLetterQuietDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterPublicTrustCap", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter Public Trust Cap", "Maximum positive or negative contribution of public trust to the trust value used for letters. Default: ±20.", TerminalSettingType.Integer, 0f, 100f, 1f, "0", s => s.NpcInitiatedLetterPublicTrustCap, (s, v) => s.NpcInitiatedLetterPublicTrustCap = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterMotiveFatigueDays", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter Motive Fatigue Days", "Duration of reduced weight when the same NPC repeats the same type of letter-writing motive. Default: 30 days.", TerminalSettingType.Integer, 0f, 120f, 1f, "0", s => s.NpcInitiatedLetterMotiveFatigueDays, (s, v) => s.NpcInitiatedLetterMotiveFatigueDays = Convert.ToInt32(v)));
