		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterTargetChars", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter Target Chars", "Target character count of an NPC proactive letter body. Default: 220 characters.", TerminalSettingType.Integer, 80f, 1000f, 1f, "0", s => s.NpcInitiatedLetterTargetChars, (s, v) => s.NpcInitiatedLetterTargetChars = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcInitiatedLetterDebugLog", TerminalCategories.Characters, "7. NPC proactive contact/NPC-initiated letters", "NPC Initiated Letter Debug Log", "Records candidate scores, probabilities, motives, cooldowns, and reasons for skipping in Mod_Logic.txt.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.NpcInitiatedLetterDebugLog, (s, v) => s.NpcInitiatedLetterDebugLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableCompanionProactiveChat", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Enable Companion Proactive Chat", "Allows companions, family members, and other Heroes in the player main party to proactively request conversations through map notifications.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableCompanionProactiveChat, (s, v) => s.EnableCompanionProactiveChat = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("CompanionProactiveChatTestMode", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Companion Proactive Chat Test Mode", "Scans every in-game hour with a 100% trigger probability and ignores cooldowns. Still requires an eligible Hero, a safe player state, and a valid motive.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.CompanionProactiveChatTestMode, (s, v) => s.CompanionProactiveChatTestMode = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("CompanionProactiveChatScanIntervalHours", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Companion Proactive Chat Scan Interval Hours", "In-game hours between scans of Heroes in the player party. Default: 24 hours.", TerminalSettingType.Integer, 1f, 168f, 1f, "0", s => s.CompanionProactiveChatScanIntervalHours, (s, v) => s.CompanionProactiveChatScanIntervalHours = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("CompanionProactiveChatGlobalCooldownDays", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Companion Proactive Chat Global Cooldown Days", "In-game days before another proactive party-chat notification can be generated after one is generated. Default: 21 days.", TerminalSettingType.Integer, 0f, 120f, 1f, "0", s => s.CompanionProactiveChatGlobalCooldownDays, (s, v) => s.CompanionProactiveChatGlobalCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("CompanionProactiveChatHeroCooldownDays", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Companion Proactive Chat Hero Cooldown Days", "In-game days before the same Hero can proactively request another conversation. Default: 48 days.", TerminalSettingType.Integer, 0f, 240f, 1f, "0", s => s.CompanionProactiveChatHeroCooldownDays, (s, v) => s.CompanionProactiveChatHeroCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("CompanionProactiveChatInteractionQuietDays", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Companion Proactive Chat Interaction Quiet Days", "Minimum in-game days after interacting with this Hero through any channel before proactive party chat is allowed. Default: 21 days.", TerminalSettingType.Integer, 0f, 120f, 1f, "0", s => s.CompanionProactiveChatInteractionQuietDays, (s, v) => s.CompanionProactiveChatInteractionQuietDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("CompanionProactiveChatNoticeLifetimeDays", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Companion Proactive Chat Notice Lifetime Days", "In-game days a proactive party-chat notification remains available; expiry counts as a polite refusal. Default: 3 days.", TerminalSettingType.Integer, 1f, 30f, 1f, "0", s => s.CompanionProactiveChatNoticeLifetimeDays, (s, v) => s.CompanionProactiveChatNoticeLifetimeDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("CompanionProactiveChatChanceMultiplier", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Companion Proactive Chat Chance Multiplier", "Overall multiplier for the daily probability of proactive chats within the player party. Default: 1.00.", TerminalSettingType.FloatingInteger, 0f, 5f, 0.05f, "0.00", s => s.CompanionProactiveChatChanceMultiplier, (s, v) => s.CompanionProactiveChatChanceMultiplier = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("CompanionProactiveChatMotiveFatigueDays", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Companion Proactive Chat Motive Fatigue Days", "Duration of reduced weight for a type of proactive party-chat motive after it is selected. Default: 30 days.", TerminalSettingType.Integer, 0f, 120f, 1f, "0", s => s.CompanionProactiveChatMotiveFatigueDays, (s, v) => s.CompanionProactiveChatMotiveFatigueDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("CompanionProactiveChatMotiveFatigueMultiplier", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Companion Proactive Chat Motive Fatigue Multiplier", "Weight multiplier for motive candidates during their fatigue period. Default: 0.25.", TerminalSettingType.FloatingInteger, 0f, 1f, 0.05f, "0.00", s => s.CompanionProactiveChatMotiveFatigueMultiplier, (s, v) => s.CompanionProactiveChatMotiveFatigueMultiplier = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("CompanionProactiveChatRecentEventWindowDays", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Companion Proactive Chat Recent Event Window Days", "Time window in which real recent events involving the Hero or player can serve as chat motives. Default: 10 days.", TerminalSettingType.Integer, 1f, 30f, 1f, "0", s => s.CompanionProactiveChatRecentEventWindowDays, (s, v) => s.CompanionProactiveChatRecentEventWindowDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("CompanionProactiveChatDebugLog", TerminalCategories.Characters, "7. NPC proactive contact/Companion proactive chat", "Companion Proactive Chat Debug Log", "Records candidates, probabilities, motives, cooldowns, and notification states in Mod_Logic.txt.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.CompanionProactiveChatDebugLog, (s, v) => s.CompanionProactiveChatDebugLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("PlayerNotorietySummaryIntervalDays", TerminalCategories.Characters, "8. Player notoriety", "Player Notoriety Summary Interval Days", "In-game days between attempts to update the rolling summary of the player public history material. Default: 3 days.", TerminalSettingType.Integer, 1f, 30f, 1f, "0", s => s.PlayerNotorietySummaryIntervalDays, (s, v) => s.PlayerNotorietySummaryIntervalDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("PlayerNotorietyMajorPromptChars", TerminalCategories.Characters, "8. Player notoriety", "Player Notoriety Major Prompt Chars", "Target character count and hard limit for the summary of the player public major history; also caps the history injected into the main chain when an NPC knows that history. AI rewrites the entire old summary instead of appending to its end. Unsummarized raw material is not injected directly into the main chain. Default: 300.", TerminalSettingType.Integer, 80f, 1000f, 1f, "0", s => s.PlayerNotorietyMajorPromptChars, (s, v) => s.PlayerNotorietyMajorPromptChars = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("PlayerNotorietyCourierRecentDistanceMultiplier", TerminalCategories.Characters, "8. Player notoriety", "Player Notoriety Courier Recent Distance Multiplier", "When the player sends a letter, the courier chain can let the target NPC know about recent player actions if the distance is less than the player vision range multiplied by this value. Default: 3.0.", TerminalSettingType.FloatingInteger, 0.5f, 10f, 0.05f, "0.0", s => s.PlayerNotorietyCourierRecentDistanceMultiplier, (s, v) => s.PlayerNotorietyCourierRecentDistanceMultiplier = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("PlayerNotorietyDebugLogs", TerminalCategories.Characters, "8. Player notoriety", "Player Notoriety Debug Logs", "When enabled, writes logs about player notoriety records, awareness checks, summaries, and injection to Mod_Logic.txt.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.PlayerNotorietyDebugLogs, (s, v) => s.PlayerNotorietyDebugLogs = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("MarriageCandidateMaxAge", TerminalCategories.Characters, "8. Marriage rules", "Marriage Candidate Maximum Age", "Used to filter the clan list of marriage candidates. Default: 55.", TerminalSettingType.Integer, 18f, 80f, 1f, "0", s => s.MarriageCandidateMaxAge, (s, v) => s.MarriageCandidateMaxAge = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MarriageCandidateMaxAgeGap", TerminalCategories.Characters, "8. Marriage rules", "Marriage Candidate Maximum Age Gap", "Used to filter the clan list of marriage candidates. Default: 25.", TerminalSettingType.Integer, 0f, 60f, 1f, "0", s => s.MarriageCandidateMaxAgeGap, (s, v) => s.MarriageCandidateMaxAgeGap = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("MarriageRequireOppositeGender", TerminalCategories.Characters, "8. Marriage rules", "Marriage Require Opposite Gender", "Retained for compatibility with old configurations; the current marriage system allows same-sex marriages. Disabled by default.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.MarriageRequireOppositeGender, (s, v) => s.MarriageRequireOppositeGender = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EditPlayerCustomPromptRule", TerminalCategories.Prompt, "9. Prompt extensions", "Edit Player Custom Prompt Rule", "Use the large-text editor to save the complete rule text.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditPlayerCustomPromptRule?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EditKingdomRebellionSystemPrompt", TerminalCategories.Prompt, "9. Prompt extensions", "Edit Kingdom Rebellion System Prompt", "Use the large-text editor to save the full system prompt for naming kingdoms founded by rebellion. The default is the current built-in system prompt; trim or rewrite it as needed.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditKingdomRebellionSystemPrompt?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EditWeeklyReportWritingRequirements", TerminalCategories.Diplomacy, "Weekly reports / bulletins/Weekly report", "Edit Weekly Report Writing Requirements", "Use the large-text editor to edit weekly-report writing requirements. The default is the built-in writing requirements. Saving a blank value injects no writing requirements.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditWeeklyReportWritingRequirements?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EditNpcPersonaGenerationRequirements", TerminalCategories.Prompt, "9. Prompt extensions", "Edit NPC Persona Generation Requirements", "Edits the full writing requirements shared by ordinary Heroes and promoted companions. The default comes from mod content and is replaced by your text after saving. Saving a blank value injects no writing requirements and retains only the JSON protocol and fact constraints.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditNpcPersonaGenerationRequirements?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EditDailyMemoryCompressionWritingRequirements", TerminalCategories.Prompt, "9. Prompt extensions", "Edit Daily Memory Compression Writing Requirements", "Edits the style and selection of information for daily compression. Output tags, publicity checks, AFEF rules, and identity-fact rules cannot be overridden.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditDailyMemoryCompressionWritingRequirements?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EditMemoryOverviewCompressionWritingRequirements", TerminalCategories.Prompt, "9. Prompt extensions", "Edit Memory Overview Compression Writing Requirements", "Edits the style and organization of memory overviews. Output tags, fact boundaries, and length ranges cannot be overridden.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditMemoryOverviewCompressionWritingRequirements?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EditMajorActionCompressionWritingRequirements", TerminalCategories.Prompt, "9. Prompt extensions", "Edit Major Action Compression Writing Requirements", "Edits the style and selection of information for rolling summaries of NPC major history. Output tags, fact boundaries, and length ranges cannot be overridden.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditMajorActionCompressionWritingRequirements?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EditPolicyPrompts", TerminalCategories.Diplomacy, "16. Policy system", "Edit Policy Prompts", "Edits the requirements for player AI drafting, player policy review, NPC ruler policies, and understanding and evaluating currently available policy effects in one place.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditPolicyPrompts?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("ManagePolicyEffectModules", TerminalCategories.Diplomacy, "16. Policy system", "Manage Policy Effect Modules", "Separately configures retrievable effect modules for player, local, NPC ruler, and vassal-state policies. Affects only policies initiated after saving.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ManagePolicyEffectModules?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("PolicyRecentActiveCount", TerminalCategories.Diplomacy, "16. Policy system", "Policy Recent Active Count", "Maximum recent active policies from the current kingdom read by player review and NPC generation. Default: 2; 0 disables this. Missing entries are not filled from elsewhere, and dialogue is unaffected.", TerminalSettingType.Integer, 0f, 10f, 1f, "0", s => s.PolicyRecentActiveCount, (s, v) => s.PolicyRecentActiveCount = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("PolicyRelatedActiveCount", TerminalCategories.Diplomacy, "16. Policy system", "Policy Related Active Count", "Reads the remaining active policies from all kingdoms by relevance. Default: 3. Deduplicates without a similarity threshold; 0 disables this, and dialogue is unaffected.", TerminalSettingType.Integer, 0f, 10f, 1f, "0", s => s.PolicyRelatedActiveCount, (s, v) => s.PolicyRelatedActiveCount = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("OpenCustomPromptTextStoreFolderAction", TerminalCategories.Prompt, "9. Prompt extensions", "Open Custom Prompt Text Store Folder Action", "Opens the CustomPrompts folder, where each set of prompt JSON files can be edited directly.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.OpenCustomPromptTextStoreFolderAction?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("UseDetailedSceneSpeechPrompt", TerminalCategories.Prompt, "9. Prompt extensions", "Use Detailed Scene Speech Prompt", "When disabled, detailed action/inner-thought text is still used, but action descriptions and inner thoughts are filtered from the output. When enabled, action descriptions and inner thoughts are retained.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.UseDetailedSceneSpeechPrompt, (s, v) => s.UseDetailedSceneSpeechPrompt = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("PreserveSceneAsteriskActions", TerminalCategories.Prompt, "9. Prompt extensions", "Preserve Scene Asterisk Actions", "When enabled, action content enclosed in **...** or *...* is not removed even if Preserve scene-shout action/inner-thought descriptions is disabled.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.PreserveSceneAsteriskActions, (s, v) => s.PreserveSceneAsteriskActions = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("DisableBuiltInSceneReplyFormatPrompt", TerminalCategories.Prompt, "9. Prompt extensions", "Disable Built In Scene Reply Format Prompt", "When enabled, the single-person conversation identity restrictions and the default reply-format/action/inner-thought/length requirements are no longer injected. Provide a complete format in Player custom rule text yourself. Disabled by default.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.DisableBuiltInSceneReplyFormatPrompt, (s, v) => s.DisableBuiltInSceneReplyFormatPrompt = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("UseAiEvaluatedCustomPolicyCost", TerminalCategories.Diplomacy, "16. Policy system/1. Player policy", "Use AI Evaluated Custom Policy Cost", "When enabled, AI evaluates the required denars from policy scale and implementation difficulty. If denars are insufficient, all policy effects are reduced in proportion to the actual contribution. When disabled, the fixed denar cost below is used.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.UseAiEvaluatedCustomPolicyCost, (s, v) => s.UseAiEvaluatedCustomPolicyCost = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("PlayerPolicyApiSourceDropdown", TerminalCategories.Diplomacy, "16. Policy system/1. Player policy", "Player Policy API Source Dropdown", "Reuses the selected chain URL, key, model, and address-parsing rules. Incomplete selected configurations automatically fall back to the main API. Explicitly selecting preprocessing is unaffected by the ordinary preprocessing API switch.", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.PlayerPolicyApiSourceDropdown?.SelectedValue ?? "", (s, v) => { if (s.PlayerPolicyApiSourceDropdown != null && v is int idx && idx >= 0 && idx < s.PlayerPolicyApiSourceDropdown.Count) { var dd = s.PlayerPolicyApiSourceDropdown; dd.SelectedIndex = idx; s.PlayerPolicyApiSourceDropdown = dd; } }, null, s => s.PlayerPolicyApiSourceDropdown));
		_allDefinitions.Add(new TerminalSettingDef("PlayerPolicyAutoDraftApiSourceDropdown", TerminalCategories.Diplomacy, "16. Policy system/1. Player policy", "Player Policy Auto Draft API Source Dropdown", "Selects only whether AI drafting uses the main chain, preprocessing, or postprocessing. Default: preprocessing. Incomplete selected configurations automatically fall back to the main endpoint; the policy-review endpoint is unaffected.", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.PlayerPolicyAutoDraftApiSourceDropdown?.SelectedValue ?? "", (s, v) => { if (s.PlayerPolicyAutoDraftApiSourceDropdown != null && v is int idx && idx >= 0 && idx < s.PlayerPolicyAutoDraftApiSourceDropdown.Count) { var dd = s.PlayerPolicyAutoDraftApiSourceDropdown; dd.SelectedIndex = idx; s.PlayerPolicyAutoDraftApiSourceDropdown = dd; } }, null, s => s.PlayerPolicyAutoDraftApiSourceDropdown));
		_allDefinitions.Add(new TerminalSettingDef("CustomPolicyGoldCost", TerminalCategories.Diplomacy, "16. Policy system/1. Player policy", "Custom Policy Gold Cost", "Used only when AI-evaluated policy cost is disabled. The specified denars are deducted when a player policy is successfully published. Default: 50000; 0 means free.", TerminalSettingType.Integer, 0f, 500000f, 1f, "0", s => s.CustomPolicyGoldCost, (s, v) => s.CustomPolicyGoldCost = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("CustomPolicyPublicFeedbackTargetChars", TerminalCategories.Diplomacy, "16. Policy system/1. Player policy", "Custom Policy Public Feedback Target Chars", "Target length of public feedback after a player policy is published. Default: about 900 characters; adjustable from 100 to 1800 characters. Actual length may vary slightly with model output.", TerminalSettingType.Integer, 100f, 1800f, 1f, "0", s => s.CustomPolicyPublicFeedbackTargetChars, (s, v) => s.CustomPolicyPublicFeedbackTargetChars = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("PlayerPolicyFollowSelectedApiTokens", TerminalCategories.Diplomacy, "16. Policy system/1. Player policy", "Player Policy Follow Selected API Tokens", "When enabled, uses the maximum output tokens of the API source actually in effect. If it falls back to the main API, the main API token limit is used instead. When disabled, always uses the custom policy value below.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.PlayerPolicyFollowSelectedApiTokens, (s, v) => s.PlayerPolicyFollowSelectedApiTokens = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("PlayerPolicyCustomMaxTokens", TerminalCategories.Diplomacy, "16. Policy system/1. Player policy", "Player Policy Custom Maximum Tokens", "Used only when Follow selected API tokens is disabled. Affects only player policies; allows 1000–100000 and does not change global limits for other APIs.", TerminalSettingType.Integer, 1000f, 100000f, 1f, "0", s => s.PlayerPolicyCustomMaxTokens, (s, v) => s.PlayerPolicyCustomMaxTokens = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("PlayerPolicyEffectPostprocessMaxTokens", TerminalCategories.Diplomacy, "16. Policy system/1. Player policy", "Player Policy Effect Postprocess Maximum Tokens", "Maximum output tokens for the player policy stage-two effects JSON. Default: 5000; the actual value never exceeds the player policy token limit currently in effect above.", TerminalSettingType.Integer, 512f, 12000f, 1f, "0", s => s.PlayerPolicyEffectPostprocessMaxTokens, (s, v) => s.PlayerPolicyEffectPostprocessMaxTokens = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("PlayerPolicyEffectModuleDetailCount", TerminalCategories.Diplomacy, "16. Policy system/1. Player policy", "Player Policy Effect Module Detail Count", "Retains old-configuration compatibility: saved values can still be 1–30, with a default of 6. At most 8 detailed rules are ultimately injected into stage two; values above 8 are treated as 8. This does not limit the internal ONNX candidate pool. Higher values consume more prompt text and tokens.", TerminalSettingType.Integer, 1f, 30f, 1f, "0", s => s.PlayerPolicyEffectModuleDetailCount, (s, v) => s.PlayerPolicyEffectModuleDetailCount = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableNpcRulerPolicy", TerminalCategories.Diplomacy, "16. Policy system/2. NPC ruler policy", "Enable NPC Ruler Policy", "When enabled, NPC kingdoms formulate and publish policies at the configured intervals. Disabling this stops new policy generation; policies already in force and their records are unaffected.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNpcRulerPolicy, (s, v) => s.EnableNpcRulerPolicy = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcRulerPolicyApiSourceDropdown", TerminalCategories.Diplomacy, "16. Policy system/2. NPC ruler policy", "NPC Ruler Policy API Source Dropdown", "Reuses the selected chain URL, key, model, and address-parsing rules. Incomplete selected configurations automatically fall back to the main API. Explicitly selecting preprocessing is unaffected by the ordinary preprocessing API switch.", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.NpcRulerPolicyApiSourceDropdown?.SelectedValue ?? "", (s, v) => { if (s.NpcRulerPolicyApiSourceDropdown != null && v is int idx && idx >= 0 && idx < s.NpcRulerPolicyApiSourceDropdown.Count) { var dd = s.NpcRulerPolicyApiSourceDropdown; dd.SelectedIndex = idx; s.NpcRulerPolicyApiSourceDropdown = dd; } }, null, s => s.NpcRulerPolicyApiSourceDropdown));
		_allDefinitions.Add(new TerminalSettingDef("NpcRulerPolicyCheckIntervalDays", TerminalCategories.Diplomacy, "16. Policy system/2. NPC ruler policy", "NPC Ruler Policy Check Interval Days", "In-game days between checks for whether a new NPC policy is needed. Default: 7 days; adjustable from 1 to 30 days. No policy is generated this round if no kingdom is eligible.", TerminalSettingType.Integer, 1f, 30f, 1f, "0", s => s.NpcRulerPolicyCheckIntervalDays, (s, v) => s.NpcRulerPolicyCheckIntervalDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcRulerPolicyIntervalDays", TerminalCategories.Diplomacy, "16. Policy system/2. NPC ruler policy", "NPC Ruler Policy Interval Days", "Minimum in-game days between two policy drafts in the same NPC kingdom. Default: 7 days; adjustable from 1 to 30 days. Normal drafts that are pending, approved, or rejected all count toward the cooldown. Player publication or renewal of a vassal-state policy is exempt, but suppresses NPC ruler policies in that target vassal state for this many days from that day onward.", TerminalSettingType.Integer, 1f, 30f, 1f, "0", s => s.NpcRulerPolicyIntervalDays, (s, v) => s.NpcRulerPolicyIntervalDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcRulerPolicyFollowSelectedApiTokens", TerminalCategories.Diplomacy, "16. Policy system/2. NPC ruler policy", "NPC Ruler Policy Follow Selected API Tokens", "When enabled, uses the maximum output tokens of the API source actually in effect. If it falls back to the main API, the main API token limit is used instead. When disabled, always uses the custom policy value below.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.NpcRulerPolicyFollowSelectedApiTokens, (s, v) => s.NpcRulerPolicyFollowSelectedApiTokens = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcRulerPolicyCustomMaxTokens", TerminalCategories.Diplomacy, "16. Policy system/2. NPC ruler policy", "NPC Ruler Policy Custom Maximum Tokens", "Used only when Follow selected API tokens is disabled. Affects only NPC ruler policies; allows 1000–100000 and does not change global limits for other APIs.", TerminalSettingType.Integer, 1000f, 100000f, 1f, "0", s => s.NpcRulerPolicyCustomMaxTokens, (s, v) => s.NpcRulerPolicyCustomMaxTokens = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableWorldDiplomacy", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/1. Basics", "Enable World Diplomacy", "When enabled, kingdoms publish diplomatic declarations, negotiate, and take diplomatic actions on their own. Diplomacy and scribe drafting reuse the event and kingdom-rebellion API, falling back to the main API if the configuration is incomplete. When disabled, native kingdom diplomatic decisions resume.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableWorldDiplomacy, (s, v) => s.EnableWorldDiplomacy = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyStartNewGameAtPeace", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/1. Basics", "World Diplomacy Start New Game At Peace", "Applies only to newly created saves, ending kingdom wars already present at the start. Disabled by default; toggling this does not reset wars in the current save.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.WorldDiplomacyStartNewGameAtPeace, (s, v) => s.WorldDiplomacyStartNewGameAtPeace = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableWorldDiplomacyMapNotifications", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/1. Basics", "Enable World Diplomacy Map Notifications", "Delivered diplomatic declarations appear as text messages at the bottom left, instead of right-side notifications. Disabling this does not affect negotiations, distribution, bulletin material, or kingdom notices.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableWorldDiplomacyMapNotifications, (s, v) => s.EnableWorldDiplomacyMapNotifications = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyMaxConcurrentOrdinaryRounds", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/2. Event pacing", "World Diplomacy Maximum Concurrent Ordinary Rounds", "Shared by ordinary automatic diplomacy and policy triggers; default: 3 events. When full, policy work remains pending while existing talks continue replying and finish. Lowering the limit does not cancel existing events. At most 1 additional event opens per day; player diplomacy and verbal-promise events do not use these slots.", TerminalSettingType.Integer, 1f, 12f, 1f, "0", s => s.WorldDiplomacyMaxConcurrentOrdinaryRounds, (s, v) => s.WorldDiplomacyMaxConcurrentOrdinaryRounds = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyActivityDropdown", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/2. Event pacing", "World Diplomacy Activity Dropdown", "Low: at most 2 kingdoms; moderate: at most 3; high: at most 5, all including the initiating kingdom. Selects only kingdoms with actual diplomatic matters and does not fill the count artificially. Default: moderate. This is the participant count for one event, not the number of concurrent events.", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.WorldDiplomacyActivityDropdown?.SelectedValue ?? "", (s, v) => { if (s.WorldDiplomacyActivityDropdown != null && v is int idx && idx >= 0 && idx < s.WorldDiplomacyActivityDropdown.Count) { var dd = s.WorldDiplomacyActivityDropdown; dd.SelectedIndex = idx; s.WorldDiplomacyActivityDropdown = dd; } }, null, s => s.WorldDiplomacyActivityDropdown));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyRoundLengthDropdown", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/2. Event pacing", "World Diplomacy Round Length Dropdown", "Typical end time for new events: compact about 15 days, standard about 21 days, relaxed about 28 days. Events may finish early on reaching an outcome or extend briefly to conclude. Default: standard; affects only new events.", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.WorldDiplomacyRoundLengthDropdown?.SelectedValue ?? "", (s, v) => { if (s.WorldDiplomacyRoundLengthDropdown != null && v is int idx && idx >= 0 && idx < s.WorldDiplomacyRoundLengthDropdown.Count) { var dd = s.WorldDiplomacyRoundLengthDropdown; dd.SelectedIndex = idx; s.WorldDiplomacyRoundLengthDropdown = dd; } }, null, s => s.WorldDiplomacyRoundLengthDropdown));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyCourtMaxDeliveryDays", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/3. Distribution", "World Diplomacy Court Maximum Delivery Days", "Allocates court delivery times by distance. Controls delivery to the farthest court and the relay pace for one round of a new event; not every kingdom waits this fixed number of days. Default: 7 days; lower values produce more frequent replies.", TerminalSettingType.Integer, 3f, 14f, 1f, "0", s => s.WorldDiplomacyCourtMaxDeliveryDays, (s, v) => s.WorldDiplomacyCourtMaxDeliveryDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyContinentSpreadDays", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/3. Distribution", "World Diplomacy Continent Spread Days", "Schedules when local nobles and civilians learn of diplomatic declarations according to distance. Default: 21 days. Does not control how often events automatically start or replace court delivery times.", TerminalSettingType.Integer, 7f, 42f, 1f, "0", s => s.WorldDiplomacyContinentSpreadDays, (s, v) => s.WorldDiplomacyContinentSpreadDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyDeclarationMinCharacters", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/4. Declarations and scribe", "Suggested declaration length lower bound", "Suggested length for AI declarations, replies, and scribe drafting, including punctuation. Simple replies may be shorter and complex terms may be longer; complete terms take priority. Default lower bound: 100, adjustable from 1 to 1000. Does not limit player editing.", TerminalSettingType.Integer, 1f, 1000f, 1f, "0", s => s.WorldDiplomacyDeclarationMinCharacters, (s, v) => s.WorldDiplomacyDeclarationMinCharacters = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyDeclarationMaxCharacters", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/4. Declarations and scribe", "Suggested declaration length upper bound", "Suggested length for AI declarations, replies, and scribe drafting, not a text cutoff; complete terms take priority. Default upper bound: 300, adjustable from 1 to 1000; values below the lower bound use that bound. Also affects scribe generation capacity. If a long draft is truncated, increase this value and the API output limit. Does not limit player editing.", TerminalSettingType.Integer, 1f, 1000f, 1f, "0", s => s.WorldDiplomacyDeclarationMaxCharacters, (s, v) => s.WorldDiplomacyDeclarationMaxCharacters = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EditWorldDiplomacyPrompt", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/4. Declarations and scribe", "Diplomatic judgment and writing preferences", "Adjust diplomatic interests, action priorities, and writing style. Custom writing preferences take precedence over default phrasing. The scribe uses only writing instructions consistent with player intent, preserving all terms when drafting or rewriting without adding substantive clauses. Blank adds no custom preferences; facts, authority, legal action requirements, and output rules remain in force.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditWorldDiplomacyPrompt?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("RestoreDefaultWorldDiplomacyPrompt", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/4. Declarations and scribe", "Restore default diplomatic judgment and writing preferences", "After confirmation, restore default diplomatic judgment and writing preferences, replacing current custom preferences. Restores preference text only; does not reset event limits, distribution, length, or protection settings.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.RestoreDefaultWorldDiplomacyPrompt?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyOffensiveWarCooldownDays", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/5. War and proposal protection", "World Diplomacy Offensive War Cooldown Days", "Minimum days after a kingdom starts a war before it can initiate another new war. Default: 42 days. Does not limit publication frequency for other diplomatic declarations.", TerminalSettingType.Integer, 7f, 120f, 1f, "0", s => s.WorldDiplomacyOffensiveWarCooldownDays, (s, v) => s.WorldDiplomacyOffensiveWarCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyPeaceProtectionDays", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/5. War and proposal protection", "World Diplomacy Peace Protection Days", "After two kingdoms make peace, ordinary diplomatic disputes cannot restart war during this period. Default: 21 days; 0 disables this protection. Other war-declaration eligibility restrictions are unaffected.", TerminalSettingType.Integer, 0f, 60f, 1f, "0", s => s.WorldDiplomacyPeaceProtectionDays, (s, v) => s.WorldDiplomacyPeaceProtectionDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyTradeAllianceFailedProposalCooldownDays", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/5. War and proposal protection", "World Diplomacy Trade Alliance Failed Proposal Cooldown Days", "After a trade or alliance proposal fails, the same proposing kingdom temporarily cannot make the same type of proposal to the same target. Reverse-direction proposals and the other proposal type are tracked separately. Default: 168 days; 0 disables this.", TerminalSettingType.Integer, 0f, 672f, 1f, "0", s => s.WorldDiplomacyTradeAllianceFailedProposalCooldownDays, (s, v) => s.WorldDiplomacyTradeAllianceFailedProposalCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyThreatComplianceIssuerRelationReward", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/5. War and proposal protection", "World Diplomacy Threat Compliance Issuer Relation Reward", "After the target kingdom explicitly complies with a condemnation or ultimatum, leaders of the issuing kingdom formal, non-mercenary vassal clans gain this relation with the current king. Settled only once per threat. Default: 10; 0 disables the reward.", TerminalSettingType.Integer, 0f, 50f, 1f, "0", s => s.WorldDiplomacyThreatComplianceIssuerRelationReward, (s, v) => s.WorldDiplomacyThreatComplianceIssuerRelationReward = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyHistoryCompressionTriggerThousands", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/6. Long-term archive (advanced)", "World Diplomacy History Compression Trigger Thousands", "Start batched compression when the long-term diplomacy archive reaches this estimated size. Default: 800 (about 800k tokens); controls backlog and frequency, not history carried by each declaration. Total declaration input has a separate 32k estimated-token cap, and each compression batch has a separate 128k input cap.", TerminalSettingType.Integer, 64f, 900f, 1f, "0", s => s.WorldDiplomacyHistoryCompressionTriggerThousands, (s, v) => s.WorldDiplomacyHistoryCompressionTriggerThousands = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyHistoryCompressionTargetThousands", TerminalCategories.Diplomacy, "17. AI diplomacy (testing)/6. Long-term archive (advanced)", "World Diplomacy History Compression Target Thousands", "Combined target for the long-term snapshot and protected facts after each compression batch. Default: 48, about 48k tokens; cap: 60k. Declarations take only relevant material, not the whole snapshot. Actual summaries are also limited by the selected API maximum output tokens.", TerminalSettingType.Integer, 8f, 60f, 1f, "0", s => s.WorldDiplomacyHistoryCompressionTargetThousands, (s, v) => s.WorldDiplomacyHistoryCompressionTargetThousands = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableNobleGathering", TerminalCategories.Diplomacy, "18. Noble gatherings", "Enable Noble Gathering", "Master gathering-system switch. Disabling it stops new gatherings; ongoing gatherings are settled as cancelled at the next safe campaign hour, and hosts and guests are scheduled to return home. No game restart is required.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNobleGathering, (s, v) => s.EnableNobleGathering = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableNpcAutomaticNobleGatherings", TerminalCategories.Diplomacy, "18. Noble gatherings", "Enable NPC Automatic Noble Gatherings", "When enabled, eligible NPCs automatically host gatherings by kingdom. Disabling it stops automatic creation of NPC gatherings; the player can still host gatherings.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNpcAutomaticNobleGatherings, (s, v) => s.EnableNpcAutomaticNobleGatherings = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("AllowNpcNobleGatheringPlayerInvitations", TerminalCategories.Diplomacy, "18. Noble gatherings", "Allow NPC Noble Gathering Player Invitations", "When enabled, NPC gatherings can invite the player and send a courier. Disabling this blocks only new invitations; invitations already sent to the player remain valid.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.AllowNpcNobleGatheringPlayerInvitations, (s, v) => s.AllowNpcNobleGatheringPlayerInvitations = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("ShowNobleGatheringGuestArrivalMessages", TerminalCategories.Diplomacy, "18. Noble gatherings", "Show Noble Gathering Guest Arrival Messages", "Controls colored messages at the bottom left when guests arrive at a player-hosted gathering. Disabling it hides only the messages; arrival checks, gathering state, and rewards are unaffected.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.ShowNobleGatheringGuestArrivalMessages, (s, v) => s.ShowNobleGatheringGuestArrivalMessages = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcNobleGatheringIntervalDays", TerminalCategories.Diplomacy, "18. Noble gatherings", "NPC Noble Gathering Interval Days", "In-game days between scheduling two automatic gatherings in the same kingdom. Default: 21 days. Calculated separately per kingdom; changes are used the next time a gathering is rescheduled.", TerminalSettingType.Integer, 7f, 120f, 1f, "0", s => s.NpcNobleGatheringIntervalDays, (s, v) => s.NpcNobleGatheringIntervalDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("AllowNpcNobleGatheringGovernorInvitations", TerminalCategories.Diplomacy, "18. Noble gatherings", "Allow NPC Noble Gathering Governor Invitations", "Affects only automatically generated NPC guest lists. When disabled, NPCs do not invite governors currently governing settlements; players hosting gatherings can still invite governors freely.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.AllowNpcNobleGatheringGovernorInvitations, (s, v) => s.AllowNpcNobleGatheringGovernorInvitations = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NobleGatheringDurationDays", TerminalCategories.Diplomacy, "18. Noble gatherings", "Noble Gathering Duration Days", "Shared by player and NPC gatherings. Default: 5 days. Changes affect only gatherings created afterward; gatherings already underway keep their original end date.", TerminalSettingType.Integer, 1f, 14f, 1f, "0", s => s.NobleGatheringDurationDays, (s, v) => s.NobleGatheringDurationDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NobleGatheringCost", TerminalCategories.Diplomacy, "18. Noble gatherings", "Noble Gathering Cost", "Shared by player and NPC hosts; the actual host pays the cost. Default: 50000 denars; 0 means free.", TerminalSettingType.Integer, 0f, 500000f, 1f, "0", s => s.NobleGatheringCost, (s, v) => s.NobleGatheringCost = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NobleGatheringInvitedClanRelationReward", TerminalCategories.Diplomacy, "18. Noble gatherings", "Noble Gathering Invited Clan Relation Reward", "Shared by player and NPC gatherings; settled only once per gathering for the host and each invited clan leader. Default: 5; 0 means no relation increase. Changes affect only gatherings created afterward.", TerminalSettingType.Integer, 0f, 20f, 1f, "0", s => s.NobleGatheringInvitedClanRelationReward, (s, v) => s.NobleGatheringInvitedClanRelationReward = Convert.ToInt32(v)));
        _allDefinitions.Add(new TerminalSettingDef("NewsMode", TerminalCategories.Diplomacy, DuelSettings.NewsSettingsGroup, "News Mode", "Choose weekly reports or bulletins; the two modes are mutually exclusive. Switching modes preserves historical archives.", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.NewsMode.SelectedValue, (s, v) => { if (v is int index) s.UseWorldBulletin = index != 0; }, null, s => s.NewsMode));
        _allDefinitions.Add(new TerminalSettingDef("AutoGenerateWorldBulletins", TerminalCategories.Diplomacy, "Weekly reports / bulletins/Bulletin", "Auto Generate World Bulletins", "Disabling this stops new bulletin generation, while recent events are still recorded for NPC awareness. Independent of automatic weekly-report generation.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.AutoGenerateWorldBulletins, (s, v) => s.AutoGenerateWorldBulletins = Convert.ToBoolean(v)));
        _allDefinitions.Add(new TerminalSettingDef("WorldBulletinReadPlayerHistory", TerminalCategories.Diplomacy, "Weekly reports / bulletins/Bulletin", "Read Player Dialogue History for Bulletins", "Default: off. When enabled, bulletins may read public-summary candidates from player dialogue memory; candidates trigger one additional privacy-review request. When disabled, neither dialogue history nor that review is used. Worldbook and game events are unaffected. Applies to the next generation; requests already sent are not recalled.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.WorldBulletinReadPlayerHistory, (s, v) => s.WorldBulletinReadPlayerHistory = Convert.ToBoolean(v)));
        _allDefinitions.Add(new TerminalSettingDef("EditWorldBulletinWritingRequirements", TerminalCategories.Diplomacy, "Weekly reports / bulletins/Bulletin", "Edit World Bulletin Writing Requirements", "Edits immediate-bulletin writing requirements separately; applies to the next request. Clearing them retains the built-in format and fact constraints.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditWorldBulletinWritingRequirements?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportLengthPreset", TerminalCategories.Diplomacy, "Weekly reports / bulletins/Weekly report", "Weekly Report Length Preset", "1 = 200–400 characters; 2 = 200–800 characters; 3 = 200–1200 characters; 4 = 200–1500 characters. Shared by world and kingdom weekly reports. Default: 2.", TerminalSettingType.Integer, 1f, 4f, 1f, "0", s => s.WeeklyReportLengthPreset, (s, v) => s.WeeklyReportLengthPreset = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportRequestsPerMinute", TerminalCategories.Diplomacy, "Weekly reports / bulletins/Weekly report", "Weekly Report Requests Per Minute", "Limits the weekly-report generation request rate during development. Default: 5; maximum 20. Helps accommodate RPM or concurrency limits of some API channels.", TerminalSettingType.Integer, 1f, 20f, 1f, "0", s => s.WeeklyReportRequestsPerMinute, (s, v) => s.WeeklyReportRequestsPerMinute = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("AutoGenerateWeeklyReports", TerminalCategories.Diplomacy, "Weekly reports / bulletins/Weekly report", "Auto Generate Weekly Reports", "When enabled, the system automatically settles the previous week at the start of each new week and generates world and kingdom weekly reports. On day 0, the opening overview is automatically recorded as a week 0 event.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.AutoGenerateWeeklyReports, (s, v) => s.AutoGenerateWeeklyReports = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportPopupBodyFontSize", TerminalCategories.Diplomacy, DuelSettings.NewsSettingsGroup, "Weekly Report Popup Body Font Size", "Affects only the body of the large popup for the latest kingdom weekly report, not other interfaces. Default: 18.", TerminalSettingType.Integer, 12f, 36f, 1f, "0", s => s.WeeklyReportPopupBodyFontSize, (s, v) => s.WeeklyReportPopupBodyFontSize = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableWeeklyReportMapNotifications", TerminalCategories.Diplomacy, DuelSettings.NewsSettingsGroup, "Enable Weekly Report Map Notifications", "When enabled, a clickable message appears at the bottom right of the campaign map when a weekly report is generated. When disabled, no message appears, and reports generated while disabled are not queued for later notification. Enabled by default.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableWeeklyReportMapNotifications, (s, v) => s.EnableWeeklyReportMapNotifications = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableWeeklyReportReadingXpReward", TerminalCategories.Diplomacy, DuelSettings.NewsSettingsGroup, "Enable Weekly Report Reading XP Reward", "When enabled, opening a weekly report from a map notification and staying for 10 full seconds accumulates experience from the character counts of its three columns. After every 20 reports studied, Charm, Leadership, and Steward experience is awarded to the player in one batch.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableWeeklyReportReadingXpReward, (s, v) => s.EnableWeeklyReportReadingXpReward = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportReadingXpPerHundredChars", TerminalCategories.Diplomacy, DuelSettings.NewsSettingsGroup, "Weekly Report Reading XP Per Hundred Chars", "Length multiplier for weekly-report reading rewards. Default: 20, meaning 20 experience in the corresponding skill per 100 valid characters/words in each column.", TerminalSettingType.Integer, 0f, 100f, 1f, "0", s => s.WeeklyReportReadingXpPerHundredChars, (s, v) => s.WeeklyReportReadingXpPerHundredChars = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportReadingXpSkillCap", TerminalCategories.Diplomacy, DuelSettings.NewsSettingsGroup, "Weekly Report Reading XP Skill Cap", "Maximum experience per skill from one weekly report. Default: 100; 0 disables weekly-report reading experience.", TerminalSettingType.Integer, 0f, 500f, 1f, "0", s => s.WeeklyReportReadingXpSkillCap, (s, v) => s.WeeklyReportReadingXpSkillCap = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableKingdomStabilityAndRebellion", TerminalCategories.Diplomacy, DuelSettings.NewsSettingsGroup, "Enable Kingdom Stability And Rebellion", "When disabled, this mod no longer triggers kingdom rebellions. Kingdom stability no longer affects loyalty in settlements directly ruled by the king or applies stability-based relation modifiers.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableKingdomStabilityAndRebellion, (s, v) => s.EnableKingdomStabilityAndRebellion = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnablePlayerKingdomRebellionImmunity", TerminalCategories.Diplomacy, DuelSettings.NewsSettingsGroup, "Enable Player Kingdom Rebellion Immunity", "When the player clan rules a kingdom or the player is its leader, enabling this stops this mod kingdom stability from applying relation modifiers, loyalty modifiers to settlements directly ruled by the king, or kingdom-rebellion checks to that kingdom. Native low-loyalty town rebellions still follow native rules.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnablePlayerKingdomRebellionImmunity, (s, v) => s.EnablePlayerKingdomRebellionImmunity = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("GcczNpcResponseUnlimited", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "GCCZ NPC Response Unlimited", "Removes the configured numeric cap in active GCCZ town scenes while retaining event deduplication and queue safety.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.GcczNpcResponseUnlimited, (s, v) => s.GcczNpcResponseUnlimited = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("GcczNpcResponseLimit", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "GCCZ NPC Response Limit", "Limits ambient NPC replies per player utterance, semantic action, or player attack event in an active GCCZ town scene.", TerminalSettingType.Integer, 1f, 20f, 1f, "0", s => s.GcczNpcResponseLimit, (s, v) => s.GcczNpcResponseLimit = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableGcczDiagnosticLog", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "Enable GCCZ Diagnostic Log", "Writes the separate GCCZ_Debug.log. Disabling this stops new log entries, while existing logs can still be exported or cleared.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableGcczDiagnosticLog, (s, v) => s.EnableGcczDiagnosticLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableGcczVerboseDiagnosticLog", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "Enable GCCZ Verbose Diagnostic Log", "Records frequent diagnostics such as NPC response caps. Enable while investigating an issue; disabling this retains key logs for stage changes, disposition results, and exceptions.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableGcczVerboseDiagnosticLog, (s, v) => s.EnableGcczVerboseDiagnosticLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("GcczDiagnosticLogMaxSizeMegabytes", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "GCCZ Diagnostic Log Maximum Size Megabytes", "GCCZ_Debug.log rotates automatically at this limit; the previous file is retained as GCCZ_Debug.previous.log. Default: 16 MB.", TerminalSettingType.Integer, 1f, 128f, 1f, "0", s => s.GcczDiagnosticLogMaxSizeMegabytes, (s, v) => s.GcczDiagnosticLogMaxSizeMegabytes = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ExportGcczDebugLog", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "Export GCCZ Debug Log", "Copies GCCZ_Debug.log from the current module Logs folder to the desktop as a separate file with a timestamp in its name.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ExportGcczDebugLog?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("ClearGcczDebugLog", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "Clear GCCZ Debug Log", "Clears only the current GCCZ_Debug.log; the previous rotated log is not deleted.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ClearGcczDebugLog?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("EnableSetsDiagnosticLog", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "Enable SETS Diagnostic Log", "Writes the separate SETS.log for settlement-entry companions and internal unrest diagnostics. Disabling this stops new log entries, while existing logs can still be exported or cleared.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableSetsDiagnosticLog, (s, v) => s.EnableSetsDiagnosticLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableSetsVerboseDiagnosticLog", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "Enable SETS Verbose Diagnostic Log", "Records frequent diagnostics such as per-frame protection, command refreshes, and troop-spawn progress. Enable while investigating stalls; disabling this retains key logs for conflict starts, waves, victories, and exceptions.", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableSetsVerboseDiagnosticLog, (s, v) => s.EnableSetsVerboseDiagnosticLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("SetsDiagnosticLogMaxSizeMegabytes", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "SETS Diagnostic Log Maximum Size Megabytes", "SETS.log rotates automatically at this limit; the previous file is retained as SETS.previous.log. Default: 16 MB.", TerminalSettingType.Integer, 1f, 128f, 1f, "0", s => s.SetsDiagnosticLogMaxSizeMegabytes, (s, v) => s.SetsDiagnosticLogMaxSizeMegabytes = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("ExportSetsDiagnosticLog", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "Export SETS Diagnostic Log", "Copies SETS.log from the current module Logs folder to the desktop as a separate file with a timestamp in its name.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ExportSetsDiagnosticLog?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("ClearSetsDiagnosticLog", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "Clear SETS Diagnostic Log", "Clears only the current SETS.log; the previous rotated log is not deleted.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ClearSetsDiagnosticLog?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("ExportNoblePrisonerEscortLog", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "Export Noble Prisoner Escort Log", "Copies NoblePrisonerEscort.log to the desktop as a separate file for investigating prisoner spawning, scene executions, and retreats from wilderness meetings.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ExportNoblePrisonerEscortLog?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("ClearNoblePrisonerEscortLog", TerminalCategories.Duel, "Siege and post-battle limits (Siege & NPC Limits)", "Clear Noble Prisoner Escort Log", "Clears only the current NoblePrisonerEscort.log; the previous rotated log is not deleted.", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.ClearNoblePrisonerEscortLog?.Invoke()));
